insert into public.alerts (mother_id, rule_id, severity, message_kn, message_en, visit_id) values ('d7befb68-feeb-5a4e-b680-0474e441ee17', 'hb_severe', 'red', 'ರಕ್ತದ ಪ್ರಮಾಣ ತುಂಬಾ ಕಡಿಮೆ ಇದೆ (6.4 g/dL). ತಕ್ಷಣ ವೈದ್ಯರನ್ನು ಕಾಣಿಸಿ.', 'Severe anaemia, Hb 6.4 g/dL. Refer without delay.', '7cdd10a9-257a-580c-8b67-cb54ea5e66ce');
insert into public.alerts (mother_id, rule_id, severity, message_kn, message_en, visit_id) values ('7af4187b-2ea9-5d46-be3b-6c5b81643d25', 'bp_high', 'red', 'ರಕ್ತದೊತ್ತಡ ತುಂಬಾ ಹೆಚ್ಚಿದೆ (164/108). ತಕ್ಷಣ ಆಸ್ಪತ್ರೆಗೆ ಕಳುಹಿಸಿ.', 'Blood pressure 164/108. Refer without delay.', 'e1f64e53-da1f-5852-82c7-20b0984f86c0');
insert into public.alerts (mother_id, rule_id, severity, message_kn, message_en, visit_id) values ('61126647-5b93-5586-bcb3-646dfd0a9bb5', 'fetal_movement', 'red', 'ಮಗುವಿನ ಚಲನೆ ಕಡಿಮೆಯಾಗಿದೆ ಎಂದು ತಾಯಿ ಹೇಳಿದ್ದಾರೆ. ತಕ್ಷಣ ಆರೋಗ್ಯ ಕೇಂದ್ರಕ್ಕೆ ಕಳುಹಿಸಿ.', 'Reduced fetal movement reported. Refer without delay.', '6706f452-aa97-53ab-ae31-10241c741994');
